/*
 * TM1637 4-Digit Clock — hours:minutes with a blinking colon
 * CLK -> D2, DIO -> D3, VCC -> 5V, GND -> GND
 */

#include <TM1637Display.h>

#define CLK 2
#define DIO 3

TM1637Display display(CLK, DIO);

int hours = 9;
int minutes = 45;
unsigned long lastTick = 0;
bool colonOn = false;

void setup() {
  display.setBrightness(7);   // 0 = dimmest, 7 = brightest
}

void loop() {
  display.showNumberDec(hours * 100 + minutes, true);

  // Blink the colon at 1 Hz
  if (millis() - lastTick >= 500) {
    lastTick = millis();
    colonOn = !colonOn;
    if (colonOn) display.showColonSegment();
    else display.hideColonSegment();
  }
}
